subscriptions.schema:
message fixture.open.Event {
	optional int32 __oneof_choice (INT(32,true));
	required group __pubsub {
		required binary message_id (STRING);
		required int64 received_micros (INT(64,true));
		required binary topic (STRING);
	}
	optional group child {
		required boolean __present;
		optional binary value (STRING);
	}
	optional group chosen_child {
		required boolean __present;
		optional binary value (STRING);
	}
	required int32 implicit (INT(32,true));
	optional int64 optional_value (INT(64,false));
	optional binary text (STRING);
}

message fixture.v1.Event {
	optional int32 __oneof_choice (INT(32,true));
	required group __pubsub {
		required binary message_id (STRING);
		required int64 received_micros (INT(64,true));
		required binary topic (STRING);
	}
	required group attributes (MAP) {
		repeated group key_value {
			required binary key (STRING);
			required group value {
				required boolean __present;
				required group numbers (LIST) {
					repeated group list {
						required int32 element (INT(32,true));
					}
				}
				optional binary value (STRING);
			}
		}
	}
	optional group child {
		required boolean __present;
		required group numbers (LIST) {
			repeated group list {
				required int32 element (INT(32,true));
			}
		}
		optional binary value (STRING);
	}
	required group children (LIST) {
		repeated group list {
			required group element {
				required boolean __present;
				required group numbers (LIST) {
					repeated group list {
						required int32 element (INT(32,true));
					}
				}
				optional binary value (STRING);
			}
		}
	}
	optional group chosen_child {
		required boolean __present;
		required group numbers (LIST) {
			repeated group list {
				required int32 element (INT(32,true));
			}
		}
		optional binary value (STRING);
	}
	optional binary chosen_data;
	optional binary data;
	required group empties (LIST) {
		repeated group list {
			required group element {
				required boolean __present;
			}
		}
	}
	optional group empty {
		required boolean __present;
	}
	optional int32 fixed32 (INT(32,false));
	optional int64 fixed64 (INT(64,false));
	optional boolean flag;
	required group flags (MAP) {
		repeated group key_value {
			required boolean key;
			required binary value (STRING);
		}
	}
	optional double fraction;
	optional binary id (STRING);
	required int32 implicit (INT(32,true));
	optional int32 kind (INT(32,true));
	optional int32 number (INT(32,true));
	optional int64 signed (INT(64,true));
	optional int32 signed_fixed32 (INT(32,true));
	optional int64 signed_fixed64 (INT(64,true));
	optional float small_fraction;
	required group tags (LIST) {
		repeated group list {
			required binary element (STRING);
		}
	}
	optional binary text (STRING);
	optional int64 unsigned (INT(64,false));
	optional int32 unsigned32 (INT(32,false));
	optional int32 zigzag32 (INT(32,true));
	optional int64 zigzag64 (INT(64,true));
}

